class JanusApiErrorImpl extends Data.Error<{
  _tag: string
  cause: any
  request: HttpClientRequest.HttpClientRequest
  response: HttpClientResponse.HttpClientResponse
}> {}

export const JanusApiError = <Tag extends string, E>(
  tag: Tag,
  cause: E,
  response: HttpClientResponse.HttpClientResponse,
): JanusApiError<Tag, E> =>
  new JanusApiErrorImpl({
    _tag: tag,
    cause,
    response,
    request: response.request,
  }) as any
